"package com.example.app.execution.service;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

import com.example.app.execution.port.ExecutionDashboardCounts;
import com.example.app.execution.port.ExecutionDashboardReadPort;
import com.example.app.execution.repository.ReportRunRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class ExecutionDashboardReadService implements ExecutionDashboardReadPort {

    private static final long RECENT_RUNS_WINDOW_DAYS = 7L;

    private final ReportRunRepository reportRunRepository;

    public ExecutionDashboardReadService(ReportRunRepository reportRunRepository) {
        this.reportRunRepository = new ReportRunRepository(
                Objects.requireNonNull(reportRunRepository, "reportRunRepository must not be null"));
    }

    @Override
    public ExecutionDashboardCounts readCountsForUser(UUID userId) {
        Objects.requireNonNull(userId, "userId must not be null");
        Instant recentCutoff = Instant.now().minus(RECENT_RUNS_WINDOW_DAYS, ChronoUnit.DAYS);
        int myOpenRuns = reportRunRepository.countOpenRunsByUserId(userId);
        int recentRuns = reportRunRepository.countRecentRunsSince(recentCutoff);
        int failedScheduledJobs = reportRunRepository.countFailedScheduledJobs();
        return new ExecutionDashboardCounts(myOpenRuns, recentRuns, failedScheduledJobs);
    }
}
"

"package com.example.app.governance.service;

import java.util.Objects;
import java.util.UUID;

import com.example.app.governance.port.GovernanceDashboardCounts;
import com.example.app.governance.port.GovernanceDashboardReadPort;
import com.example.app.governance.repository.GovernanceTicketRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class GovernanceDashboardReadService implements GovernanceDashboardReadPort {

    private final GovernanceTicketRepository governanceTicketRepository;

    public GovernanceDashboardReadService(GovernanceTicketRepository governanceTicketRepository) {
        this.governanceTicketRepository = new GovernanceTicketRepository(
                Objects.requireNonNull(governanceTicketRepository, "governanceTicketRepository must not be null"));
    }

    @Override
    public GovernanceDashboardCounts readCountsForUser(UUID userId) {
        Objects.requireNonNull(userId, "userId must not be null");
        int myTodoCount = governanceTicketRepository.countTodoForUser(userId);
        int awaitingApproval = governanceTicketRepository.countAwaitingApprovalForUser(userId);
        return new GovernanceDashboardCounts(myTodoCount, awaitingApproval);
    }
}
"

