import com.example.app.governance.port.GovernanceDashboardCounts;
import com.example.app.governance.port.GovernanceDashboardReadPort;
import com.example.app.iam.security.AuthenticatedPrincipal;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class DashboardWidgetAggregator {

    private final ExecutionDashboardReadPort executionDashboardReadPort;
    private final GovernanceDashboardReadPort governanceDashboardReadPort;

    public DashboardWidgetAggregator(
            ExecutionDashboardReadPort executionDashboardReadPort,
            GovernanceDashboardReadPort governanceDashboardReadPort) {
        this.executionDashboardReadPort = Objects.requireNonNull(
                executionDashboardReadPort, "executionDashboardReadPort must not be null");
        this.governanceDashboardReadPort = Objects.requireNonNull(
                governanceDashboardReadPort, "governanceDashboardReadPort must not be null");
    }

    public DashboardWidgetsResponse getDashboardWidgets(AuthenticatedPrincipal principal) {
        Objects.requireNonNull(principal, "principal must not be null");
        ExecutionDashboardCounts execCounts =
                executionDashboardReadPort.readCountsForUser(principal.userId());
        GovernanceDashboardCounts govCounts =
                governanceDashboardReadPort.readCountsForUser(principal.userId());
        return new DashboardWidgetsResponse(
                execCounts.myOpenRuns(),
                execCounts.recentRuns(),
                govCounts.myTodoCount(),
                govCounts.awaitingApproval(),
                execCounts.failedScheduledJobs());
    }
}
